async panelProbe(mode: PanelProbeMode, value?: number): Promise<PanelProbeStatus> {
  this.panelProbeCalls.push({ mode, value })
  if (mode === 'enable' || mode === 'disable') {
    this.panelProbeEnabled = mode === 'enable'
    this.panelProbeAdvertised = false
    this.panelProbeBaselineSent = false
  }
  const ready = this.panelProbeEnabled && this.panelProbeAdvertised
  const sent = ready && ['baseline', 'zoom', 'physical', 'apply'].includes(mode) && (mode === 'baseline' || this.panelProbeBaselineSent)
  if (mode === 'baseline' && sent) this.panelProbeBaselineSent = true
  return {
    enabled: this.panelProbeEnabled, advertised: ready,
    baselineSent: this.panelProbeBaselineSent,
    state: sent ? 'LOCAL_SENT' : !this.panelProbeEnabled ? 'OFF' : ready ? 'DESCRIPTOR_OFFERED' : 'RECONNECT_REQUIRED',
    detail: sent ? 'Encrypted AirPlay event written. No iOS acknowledgement or visual effect proven.' : undefined,
    ack: 'NOT_OBSERVED', visualEffect: 'UNKNOWN', mode, value,
  }
}

